const topPriorityOpenIssues = `-- name: TopPriorityOpenIssues :many
SELECT id, title, priority
FROM zdx_issues
WHERE project_id = $1 AND status = 'open' AND priority != ''
ORDER BY priority, created_at
LIMIT 5
`

type TopPriorityOpenIssuesRow struct {
	ID       string `db:"id" json:"id"`
	Title    string `db:"title" json:"title"`
	Priority string `db:"priority" json:"priority"`
}

// metaquery: off
func (q *Queries) TopPriorityOpenIssues(ctx context.Context, projectID int32) ([]TopPriorityOpenIssuesRow, error) {
	rows, err := q.db.Query(ctx, topPriorityOpenIssues, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TopPriorityOpenIssuesRow
	for rows.Next() {
		var i TopPriorityOpenIssuesRow
		if err := rows.Scan(&i.ID, &i.Title, &i.Priority); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateIssue = `-- name: UpdateIssue :exec
UPDATE zdx_issues
SET title      = COALESCE(NULLIF($1, ''),      title),
    context    = COALESCE(NULLIF($2, ''),    context),
    priority   = COALESCE(NULLIF($3, ''),   priority),
    issue_type = COALESCE(NULLIF($4, ''), issue_type),
    updated_at = NOW()
WHERE project_id = $5 AND id = $6
`

type UpdateIssueParams struct {
	Title     interface{} `db:"title" json:"title"`
	Context   interface{} `db:"context" json:"context"`
	Priority  interface{} `db:"priority" json:"priority"`
	IssueType interface{} `db:"issue_type" json:"issue_type"`
	ProjectID int32       `db:"project_id" json:"project_id"`
	ID        string      `db:"id" json:"id"`
}

func (q *Queries) UpdateIssue(ctx context.Context, arg UpdateIssueParams) error {
	_, err := q.db.Exec(ctx, updateIssue,
		arg.Title,
		arg.Context,
		arg.Priority,
		arg.IssueType,
		arg.ProjectID,
		arg.ID,
	)
	return err
}
